import org.springframework.util.CollectionUtils;import java.util.*;// 检查集合是否为 null 或空boolean isEmpty1 = CollectionUtils.isEmpty(null);                 // trueboolean isEmpty2 = CollectionUtils.isEmpty(Collections.emptyList()); // true// 查找两个列表的交集List&lt;String&gt; list1 = Arrays.asList(&quot;a&quot;, &quot;b&quot;, &quot;c&quot;);List&lt;String&gt; list2 = Arrays.asList(&quot;b&quot;, &quot;c&quot;, &quot;d&quot;);Collection&lt;String&gt; intersection = CollectionUtils.intersection(list1, list2); // [b, c]

